  ui_story_31200601_15_dialog_content = "Hola, para garantizar su seguridad y la seguridad de Gannon City, tome este volante. Gracias.",
  ui_story_31200601_16_dialog_content = "Hedy?",
  ui_story_31200601_17_dialog_content = "¡¿PlayerName?!",
  ui_story_31200601_18_dialog_content = "Lo sabía. Nadie más me daría la hora del día.",
  ui_story_31200601_19_dialog_content = "Pensé que tenía a la persona equivocada, pero realmente eres tú.",
  ui_story_31200601_20_dialog_content = "¿Por qué repartes volantes en Gannon?",
  ui_story_31200601_21_dialog_content = "Bueno, yo tampoco esperaba que esto sucediera...",
  ui_story_31200601_22_dialog_content = "<color=#e8d9bb>Hace una semana</color>",
  ui_story_31200601_23_dialog_content = "Recibí una invitación de Illumina Federation para ser coanfitrión de un evento con Lumopolis.",
  ui_story_31200601_24_dialog_content = "Esta vez, es la Oficina de Seguridad y el templo los que enviarán cada uno un representante para participar en un intercambio cultural.",
  ui_story_31200601_25_dialog_content = "Les gustaría que escogiéramos a alguien con más <color=#FFB400>sano</color> image para actuar como sheriff por un día en Gannon.",
  ui_story_31200601_26_dialog_content = "Saludable, dices...",
  ui_story_31200601_27_dialog_content = "Pittman es el primero en salir de la carrera.",
  ui_story_31200601_28_dialog_content = "Seguido de cerca por Matthieu.",
  ui_story_31200601_29_dialog_content = "Y por último, yo.",
  ui_story_31200601_30_dialog_content = "Solo obtienes una apariencia de autoconciencia en momentos como este.",
  ui_story_31200601_31_dialog_content = "No entiendo por qué este payaso me excluiría.",
  ui_story_31200601_32_dialog_content = "Pero de todos modos, la idea de mezclarme con los plebeyos me enferma.",
  ui_story_31200601_33_dialog_content = "Estoy muy ocupado estos días, así que tampoco me cuentes.",
  ui_story_31200601_34_dialog_content = "Erica podría haber sido franca, pero los hechos son los hechos. No soy adecuado para la ocasión.",
  ui_story_31200601_35_dialog_content = "En realidad, tengo un buen prospecto en mente.",
  ui_story_31200601_36_dialog_content = "Nunca imaginé que un asunto como este sería de tanto interés para ti, Irridon.",
  ui_story_31200601_37_dialog_content = "Voy a tener que verte bajo una nueva luz.",
  ui_story_31200601_38_dialog_content = "Deja de decir tonterías.",
  ui_story_31200601_39_dialog_content = "Acabo de ver el puesto de reclutamiento para el sheriff temporal, y esta persona me vino a la mente de inmediato.",
  ui_story_31200601_40_dialog_content = "Aunque nunca vi la publicación que mencionas, creo que sé lo que quieres decir.",
  ui_story_31200601_41_dialog_content = "Es como si tuvieras una epifanía repentina... Sí, eso es todo.",
  ui_story_31200601_42_dialog_content = "¿Por qué no votamos? De esa manera, quien sea elegido no puede negarse.",
  ui_story_31200601_43_dialog_content = "Tengo la sensación de que no estás tramando nada bueno de alguna manera.",
  ui_story_31200601_44_dialog_content = "A pesar de eso, estoy a favor de votar.",
  ui_story_31200601_45_dialog_content = "Entonces decidamos con una encuesta.",
  ui_story_31200601_46_dialog_content = "<color=#e8d9bb>Esta mañana</color>",
  ui_story_31200601_47_dialog_content = "¡Estoy aquí para recogerla, señorita Hedy!",
  ui_story_31200601_48_dialog_content = "¿Eh? ¿Para qué?",
  ui_story_31200601_49_dialog_content = "Se supone que hoy eres el sheriff. ¿Has olvidado?",
  ui_story_31200601_50_dialog_content = "Suspiro, estoy seguro de que se olvidó a propósito.",
  ui_story_31200601_51_dialog_content = "No soy sordo, E-ri-ca.",
  ui_story_31200601_52_dialog_content = "Y no, no me olvidé.",
  ui_story_31200601_53_dialog_content = "Es solo que he estado demasiado ocupado últimamente.",
  ui_story_31200601_54_dialog_content = "Has recibido tu uniforme, ¿verdad? ¿Encajó?",
  ui_story_31200601_55_dialog_content = "¿Deseas cambiarlo en Illumina?",
  ui_story_31200601_56_dialog_content = "Sí, absolutamente no quiero que me vean en eso.",
  ui_story_31200601_57_dialog_content = "Muy bien, entonces, ¡vamos!",
  ui_story_31200601_58_dialog_content = "No puedo creer que todos votaron por mí cuando yo no estaba allí...",
  ui_story_31200601_59_dialog_content = "Apuesto a que fue idea de Erica.",
  ui_story_31200601_60_dialog_content = "Como Caballero de Lumopolis, nunca imaginé que usaría un uniforme de Illumina.",
  ui_story_31200601_61_dialog_content = "Probablemente todos piensen que soy un bicho raro por usar este atuendo totalmente inadecuado.",
  ui_story_31200601_62_dialog_content = "Por eso nadie se lleva el volante.",
  ui_story_31200601_63_dialog_content = "Pero fue hecho a medida para el representante de Lumopolis para el evento.",
  ui_story_31200601_64_dialog_content = "Si crees que no te queda bien, debe ser mi culpa por no pasar las medidas correctas.",
  ui_story_31200601_65_dialog_content = "No supe transmitir tus cualidades a Logística...",
  ui_story_31200601_66_dialog_content = "Lo arruiné todo... lo siento...",
  ui_story_31200601_67_dialog_content = "¡N-No, eso no es lo que quise decir!",
  ui_story_31200601_68_dialog_content = "Esto no es tu culpa. Estaba siendo demasiado histérica.",
  ui_story_31200601_69_dialog_content = "Tampoco creo que hayas hecho nada malo, Cordy, así que no te culpes.",
  ui_story_31200601_70_dialog_content = "Lo mismo ocurre con Hedy. Creo que todos en el templo votaron por ti porque eres el mejor candidato para el puesto.",
  ui_story_31200601_71_dialog_content = "Quiero decir, ¡ni siquiera te reconocí cuando tomé el volante!",
  ui_story_31200601_72_dialog_content = "Parecías absolutamente un sheriff de Gannon.",
  ui_story_31200601_73_dialog_content = "No creo que tengas nada de qué preocuparte.",
  ui_story_31200601_74_option_content = "Este atuendo no te queda raro.",
  ui_story_31200601_75_dialog_content = "¡En realidad exudas un encanto diferente al habitual en él!",
  ui_story_31200601_76_option_content = "Ya estás deslumbrante, Hedy.",
  ui_story_31200601_77_dialog_content = "Ahora el uniforme también engloba por completo tu particular encanto.",
  ui_story_31200601_78_dialog_content = "Si me preguntas, a todos les gustas sin importar cómo te veas.",
  ui_story_31200601_79_dialog_content = "Gracias. Me siento mucho mejor escuchando tus palabras.",
  ui_story_31200601_80_dialog_content = "Pero los volantes...",
  ui_story_31200601_81_dialog_content = "La gente probablemente esté demasiado ocupada para agarrarlos en este momento.",
  ui_story_31200601_82_dialog_content = "¿Por qué no haces el otro trabajo primero y te ayudo a repartirlo más tarde?",
  ui_story_31200601_83_dialog_content = "¿Qué sigue en la agenda, Cordy?",
  ui_story_31200601_84_dialog_content = "Ir a la estación y transmitir mensajes de seguridad para los pasajeros.",
  ui_story_31200601_85_dialog_content = "Si eso no implica estar de pie entre una multitud, ¡me resulta mucho más agradable!",
  ui_story_31200601_86_dialog_content = "Por favor, déjame la tarea a mí.",
  ui_story_31200601_87_dialog_content = "Eres realmente impresionante. ¡Todo el mundo recibe una serenata de la cadencia de tu elocuente y elegante voz!",
  ui_story_31200601_88_dialog_content = "Es más como escuchar un cuento de hadas que mensajes de servicio público.",
  ui_story_31200601_89_dialog_content = "Estás fascinado todo el tiempo, y se acaba antes de que te des cuenta.",
  ui_story_31200601_90_dialog_content = "Esto es bastante fácil para alguien como yo que solía trabajar con el Coro.",
  ui_story_31200601_94_dialog_content = "¡Ayuda, un niño se cayó de la plataforma!",
  ui_story_31200601_96_dialog_content = "<color=#e8d9bb>Choo! Clang, clang, clang...</color>",
  ui_story_31200601_97_dialog_content = "¡Oh no, el tren está llegando!",
  ui_story_31200601_98_dialog_content = "Toma los volantes, PlayerName!",
  ui_story_31200601_99_dialog_content = "¡Detén el tren, Pompeyo! ¡Debo salvar al niño!",
  ui_story_31200601_100_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_31200601_101_dialog_content = "¡Rápido, Cordy, vayamos a la plataforma!",
  ui_story_31200601_102_dialog_content = "¡Sí!",
  ui_story_31200601_103_dialog_content = "Gracias por salvar a mi hijo. no se como te lo puedo pagar...",
  ui_story_31200601_104_dialog_content = "Solo le di la espalda por un segundo y antes de que me diera cuenta, se había caído.",
  ui_story_31200601_105_dialog_content = "Por favor, preste más atención la próxima vez.",
  ui_story_31200601_106_dialog_content = "¡Esto no volverá a suceder! ¡Gracias!",
  ui_story_31200601_108_dialog_content = "De nada. El niño está a salvo, eso es todo lo que importa.",
  ui_story_31200601_109_dialog_content = "Ella saltó a la acción cuando todos los demás todavía estaban en pánico. Que increible.",
  ui_story_31200601_110_dialog_content = "Estás bien. Y parece que es sheriff, ¡no es de extrañar!",
  ui_story_31200601_112_dialog_content = "Ejem, ya que todo está bien ahora, debería irme.",
  ui_story_31200601_113_dialog_content = "¿Es usted tímida, señorita Hedy? ¡No esperaba que te vieras tan lindo cuando eres tímido!",
  ui_story_31200601_114_dialog_content = "... No soy tímido.",
  ui_story_31200601_115_dialog_content = "¿Qué sigue en el expediente, Cordy? Deberíamos seguir adelante.",
  ui_story_31200601_116_dialog_content = "Lo último es dar un informe público de su trabajo del día en la plaza de la estación.",
  ui_story_31200601_117_dialog_content = "No hay problema. Vamos.",
  ui_story_31200601_118_dialog_content = "...",
  ui_story_31200601_119_dialog_content = "¿Qué pasa, Hedy? ¿Estás bien?",
  ui_story_31200601_120_dialog_content = "¿Te lastimaste al salvar a ese niño?",
  ui_story_31200601_121_dialog_content = "No, de repente estoy tan nervioso.",
  ui_story_31200601_122_dialog_content = "Lógicamente, el debriefing debería ser fácil para mí.",
  ui_story_31200601_123_dialog_content = "Pero cuando pienso en retrospectiva, nada salió bien hoy.",
  ui_story_31200601_124_dialog_content = "No pude repartir suficientes volantes, luego ocurrió el accidente en la estación...",
  ui_story_31200601_125_dialog_content = "Me siento estresado y ansioso como nunca antes.",
  ui_story_31200601_126_dialog_content = "Tal vez ignoren el informe tal como lo hicieron con los volantes.",
  ui_story_31200601_127_dialog_content = "No te preocupes, Hedy, nos tienes.",
  ui_story_31200601_128_dialog_content = "Solo sube al escenario y haz lo tuyo. Los oyentes vendrán.",
  ui_story_31200601_129_dialog_content = "PlayerName es correcto. ¡Tenga fe en su encanto, señorita Hedy!",
  ui_story_31200601_130_dialog_content = "¡Al menos nos tendrás a nosotros dos como tu audiencia leal!",
  ui_story_31200601_131_dialog_content = "No esperaba recibir aliento de ustedes dos...",
  ui_story_31200601_132_dialog_content = "Muy bien... Tengo esto.",
  ui_story_31200601_133_dialog_content = "Es solo un discurso. Un pedazo de pastel para alguien tan excepcional como yo.",
  ui_story_31200601_134_dialog_content = "Buenas tardes a todos. Soy Hedy, jueza de Lumopolis.",
  ui_story_31200601_135_dialog_content = "Ha sido un honor para mí visitar y servir a Gannon como sheriff por un día.",
  ui_story_31200601_136_dialog_content = "Sabía que a nadie le importaba...",
  ui_story_31200601_137_dialog_content = "Hola, para garantizar su seguridad y la seguridad de Gannon City, tome este volante. Gracias.",
  ui_story_31200601_138_dialog_content = "Y por favor escuche el discurso en curso también.",
  ui_story_31200601_139_dialog_content = "Es una sheriff muy trabajadora y está informando sobre su experiencia en este momento.",
  ui_story_31200601_140_dialog_content = "¿Mmm? Es PlayerName ayudarme con la promoción?",
  ui_story_31200601_141_dialog_content = "Oye, ¿la chica en el escenario no es la sheriff que acaba de salvar a alguien en la estación?",
  ui_story_31200601_142_dialog_content = "¡Sí, es ella! Escuchemos lo que tiene que decir.",
  ui_story_31200601_143_dialog_content = "La gente está... viniendo... Bueno, ¡supongo que lo daré todo ahora!",
  ui_story_31200601_144_dialog_content = "Ejem. Para mejorar la sensación de seguridad y la seguridad de todos en Gannon City...",
  ui_story_31200601_145_dialog_content = "Hice las siguientes tres tareas en mi papel como sheriff...",
  ui_story_31200601_146_dialog_content = "<color=#e8d9bb>Diez minutos tarde</color>",
  ui_story_31200601_147_dialog_content = "(Todo el mundo es todo oídos...)",
  ui_story_31200601_148_dialog_content = "(Una Hedy segura de sí misma realmente sobresale en todo).",
  ui_story_31200601_149_dialog_content = "Aprecio mucho todo su apoyo y reconocimiento, y aplicaré lo que aprendí en mis propias funciones a partir de ahora.",
  ui_story_31200601_150_dialog_content = "Ese es mi discurso. Gracias a todo Gannon una vez más.",
  ui_story_31200601_151_dialog_content = "¡Lo hiciste bien!",
  ui_story_31200601_152_dialog_content = "¿Por qué no permanecer como sheriff permanente?",
  ui_story_31200601_153_dialog_content = "¡Buen discurso, Hedy!",
  ui_story_31200601_154_dialog_content = "Mira, incluso todos los volantes han sido tomados.",
  ui_story_31200601_155_dialog_content = "Es una lástima que no tuviste otra oportunidad de repartirlos tú mismo.",
  ui_story_31200601_156_dialog_content = "Completas todas tus tareas a la perfección. ¡Supongo que eso significa que el evento ha llegado a un cierre exitoso!",
  ui_story_31200601_157_dialog_content = "¡Esa es la señorita Hedy que conozco!",
  ui_story_31200601_158_dialog_content = "Gracias, PlayerName y Cordy.",
  ui_story_31200601_159_dialog_content = "Sé que logré hacer todo hoy solo porque los tuve a ustedes dos.",
  ui_story_31200601_160_dialog_content = "Me sentía un poco deprimido antes.",
  ui_story_31200601_161_dialog_content = "Pero en general, no está mal ser sheriff.",
  ui_story_31200601_162_dialog_content = "Y creo que el uniforme también me queda bastante bien.",
  ui_story_31200601_163_dialog_content = "<color=#e8d9bb>Un dia despues</color>",
  ui_story_31200601_164_dialog_content = "Oye, mira quién ha vuelto.",
  ui_story_31200601_165_dialog_content = "Pareces estar de buen humor, Hedy. El evento salió bien, ¿supongo?",
  ui_story_31200601_166_dialog_content = "Probablemente no lo admitirá, pero puedo decir que le gusta mucho el uniforme.",
  ui_story_31200601_167_dialog_content = "Puedo sentir lo cálida y confusa que se siente por dentro cuando está dentro.",
  ui_story_31200601_168_dialog_content = "Ya te dije antes, Erica, que puedo escuchar todo lo que dices.",
  ui_story_31200601_169_dialog_content = "Por cierto, ¿cuándo te quitarás ese atuendo funky?",
  ui_story_31200601_170_dialog_content = "Bueno, somos la División de Investigación de Herejes, y esta es la única manera de acercarnos a ellos.",
  ui_story_31200601_171_dialog_content = "Este atuendo nos permite acercarnos a la verdad de este mundo.",
  ui_story_31200601_172_dialog_content = "Es difícil dejarlo.",
  ui_story_31200601_173_dialog_content = "Lo que sea que haga contigo...",
  ui_story_31200601_174_dialog_content = "Ven, dame un resumen de todo el trabajo que completaste ayer.",
  ui_story_31200601_175_dialog_content = "¿No podemos seguir hablando de ropa, señorita Hedy?",
  ui_story_31200601_176_dialog_content = "Oye, espera... ¿Qué es esto?",
  ui_story_31200601_177_dialog_content = "¿Un certificado de mérito?",
  ui_story_31200601_178_dialog_content = "\"Mención al alguacil honorario de la ciudad de Gannon, destinatario: Hedy\".",
  ui_story_31200601_179_dialog_content = "Como era de esperar de Hedy, la que lo hace todo a la perfección."
}
